def fib_mod(n: int, m: int) -> int:
    # fast doubling: returns (F(k) mod m, F(k+1) mod m)
    def fd(k: int) -> tuple[int, int]:
        if k == 0:
            return 0, 1 % m
        a, b = fd(k >> 1)
        c = (a * ((2 * b - a) % m)) % m
        d = (a * a + b * b) % m
        if k & 1:
            return d, (c + d) % m
        return c, d

    return fd(n)[0] % m
